import 'package:flutter/material.dart';
import '../../services/api_client.dart';
class InterviewScreen extends StatefulWidget{const InterviewScreen({super.key,required this.api,required this.onActivity});final ApiClient api;final VoidCallback onActivity;@override State<InterviewScreen>createState()=>_InterviewScreenState();}
class _InterviewScreenState extends State<InterviewScreen>{final answer=TextEditingController();String result='';bool busy=false;Future<void>submit()async{if(answer.text.trim().isEmpty||busy)return;setState(()=>busy=true);try{final x=await widget.api.post('/interview',{'answer':answer.text});if(!mounted)return;setState(()=>result=x['answer']?.toString()??'');}catch(e){if(mounted)setState(()=>result='AIへの接続に失敗しました。${e.toString()}');}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){answer.dispose();super.dispose();}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('AI模擬面接（STAR法）',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('これまでに困難な状況やトラブルに直面した際、どのように自分で考え行動し、乗り越えましたか？'))),const SizedBox(height:12),TextField(controller:answer,onChanged:(_)=>widget.onActivity(),minLines:5,maxLines:10,decoration:const InputDecoration(labelText:'回答')),const SizedBox(height:12),FilledButton(onPressed:busy?null:submit,child:Text(busy?'分析中…':'AIフィードバックを受ける')),if(result.isNotEmpty)Card(margin:const EdgeInsets.only(top:16),child:Padding(padding:const EdgeInsets.all(16),child:Text(result)))]) ;}
